 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_envase_reservation_root_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.programacao_producao%ROWTYPE; l public.lotes%ROWTYPE; o public.ordens_servico%ROWTYPE;
BEGIN
 IF NEW.status::text<>'reservado' OR NEW.reservado_para_os_tipo IS DISTINCT FROM 'manual' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.lote_id IS NOT DISTINCT FROM OLD.lote_id AND NEW.reservado_para_os_id IS NOT DISTINCT FROM OLD.reservado_para_os_id THEN RETURN NEW; END IF;
 SELECT * INTO o FROM public.ordens_servico WHERE id=NEW.reservado_para_os_id;
 SELECT * INTO p FROM public.programacao_producao WHERE ordem_servico_id=o.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT * INTO l FROM public.lotes WHERE id=NEW.lote_id;
 IF o.status::text NOT IN ('em_cq','envase','pronto_entrega') OR l.programacao_id IS DISTINCT FROM p.id OR l.organization_id IS DISTINCT FROM o.organization_id OR p.organization_id IS DISTINCT FROM o.organization_id
 OR NEW.produto_id IS DISTINCT FROM p.produto_id OR NEW.microrganismo_id IS DISTINCT FROM p.microrganismo_id OR NEW.reservado_para_cliente_id IS DISTINCT FROM o.cliente_id
 OR (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=o.id)<>1 THEN RAISE EXCEPTION 'ENVASE_RESERVATION_LINEAGE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_p1_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 v_org uuid := public.h15_actor_organization();
 v_ref uuid;
 v_lote public.lotes%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND NOT platform_private.stock_p1_lote_owned(OLD.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 IF NOT platform_private.stock_p1_lote_owned(NEW.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_lote FROM public.lotes WHERE id=NEW.lote_id;
 -- Explicit lote ownership is required; parent references never assign ownership.
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.programacao_producao p
   WHERE p.id=v_lote.programacao_id AND p.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.envase_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.envase e WHERE e.id=NEW.envase_id
   AND e.lote_id=NEW.lote_id AND e.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_cliente_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.clientes c WHERE c.id=NEW.reservado_para_cliente_id AND c.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_partner_id IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(NEW.reservado_para_partner_id,false),false) THEN
  RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF NEW.reservado_para_partner_order_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.reservado_para_partner_order_id
    AND o.partner_id=NEW.reservado_para_partner_id
    AND public.b2b_phase1_order_visible(o.id)
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_os_id IS NOT NULL THEN
  IF NEW.reservado_para_os_tipo IN ('onfarm','on_farm') THEN
   SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o
    JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.reservado_para_os_id;
  ELSIF NEW.reservado_para_os_tipo IN ('manual','b2b') THEN
   SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.reservado_para_os_id;
  ELSE
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF v_ref IS DISTINCT FROM v_org THEN
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_lane_enqueue_solicitacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; v_out uuid:=gen_random_uuid(); v_ev uuid:=gen_random_uuid(); v_num text; v_ver bigint; v_idem text; v_by uuid; j platform_private.tenant_smtp_dispatch_jobs;
BEGIN
 IF OLD.consultor_atribuido IS NOT NULL OR NEW.consultor_atribuido IS NULL THEN RETURN NULL; END IF;
 BEGIN
  SELECT c.organization_id INTO v_org FROM public.clientes c WHERE c.id=NEW.cliente_id;
  IF v_org IS NULL OR NOT platform_private.tenant_smtp_lane_ready(v_org) THEN RETURN NULL; END IF;
  IF platform_private.tenant_smtp_lane_source_reason(NEW.id,NEW.cliente_id,v_org,NEW.consultor_atribuido) IS NOT NULL THEN RETURN NULL; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('tenant_smtp_lane_enqueue:'||v_org::text,0));
  IF (SELECT count(*) FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '1 hour')>=50 THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_jobs WHERE contract='solicitacao_atribuida_consultor_v1' AND source_id=NEW.id AND recipient_user_id=NEW.consultor_atribuido) THEN RETURN NULL; END IF;
  v_num:=left(regexp_replace(coalesce(NEW.numero_solicitacao::text,''),'[^A-Za-z0-9/._-]','','g'),40);
  SELECT version INTO v_ver FROM public.communication_tenant_email_settings WHERE organization_id=v_org;
  SELECT changed_by INTO v_by FROM platform_private.tenant_smtp_activation WHERE organization_id=v_org AND active;
  v_idem:='tsmtp:sa:'||NEW.id::text||':'||NEW.consultor_atribuido::text;
  INSERT INTO public.comunicacao_eventos(id,event_key,source_type,source_id,payload,occurred_at,created_by,idempotency_key,status,processed_at,outbox_enqueued,outbox_skipped)
   VALUES(v_ev,'tenant.smtp.solicitacao_atribuida','portal_solicitacoes',NEW.id,jsonb_build_object('contract','solicitacao_atribuida_consultor_v1'),clock_timestamp(),auth.uid(),v_idem,'processed',clock_timestamp(),1,0);
  INSERT INTO platform_private.tenant_smtp_dispatch_insert_tickets VALUES(v_out,txid_current(),v_org,NEW.consultor_atribuido,NEW.id);
  INSERT INTO public.comunicacao_outbox(id,event_id,template_chave,template_versao,template_snapshot,canal,recipient_user_id,payload_snapshot,status,attempts,max_attempts,locked_by,idempotency_key)
   VALUES(v_out,v_ev,'solicitacao_atribuida_consultor_v1',1,jsonb_build_object('canal','email','contract','solicitacao_atribuida_consultor_v1'),'email',NEW.consultor_atribuido,
    jsonb_strip_nulls(jsonb_build_object('numero',nullif(v_num,''),'tipo_demanda',left(NEW.tipo_demanda::text,40),'urgencia',left(NEW.urgencia::text,20))),
    'processing',0,1,'tenant_smtp_lane',v_idem);
  DELETE FROM platform_private.tenant_smtp_dispatch_insert_tickets WHERE outbox_id=v_out;
  IF NOT EXISTS(SELECT 1 FROM public.comunicacao_outbox WHERE id=v_out) THEN RAISE EXCEPTION 'lane_insert_contained'; END IF;
  INSERT INTO platform_private.tenant_smtp_dispatch_jobs(outbox_id,organization_id,contract,source_id,cliente_id,recipient_user_id,version,activated_by,state)
   VALUES(v_out,v_org,'solicitacao_atribuida_consultor_v1',NEW.id,NEW.cliente_id,NEW.consultor_atribuido,v_ver,v_by,'queued') RETURNING * INTO j;
  PERFORM platform_private.tenant_smtp_lane_log(j,'enqueued',NULL,auth.uid());
 EXCEPTION WHEN OTHERS THEN RETURN NULL;
 END;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION private.guard_os_separate_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_origin text; v_org uuid;
BEGIN
 IF TG_OP='INSERT' THEN
 -- Criação normal exclusivamente aberta, inclusive pelo serviço/DEFINER.
 -- NULL e qualquer estado avançado não podem saltar a aprovação humana.
 -- Sem whitelist service_role, flags GUC ou reparo de históricos.
 IF NEW.status::text IS DISTINCT FROM 'aberta' THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
 END IF;
 IF NEW.status::text IS DISTINCT FROM 'aprovada' THEN RETURN NEW; END IF;
 v_origin:=CASE TG_TABLE_NAME WHEN 'ordens_servico' THEN 'manual' WHEN 'ordens_servico_onfarm' THEN 'onfarm' END;
 IF TG_WHEN='BEFORE' THEN
 -- Um único UPDATE não pode substituir a identidade/referências e aprovar o estado anterior.
 IF (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=private.assert_os_approval_scope(OLD.id,v_origin);
 RETURN NEW;
 END IF;
 IF OLD.status::text='aberta' THEN
 v_org:=private.assert_os_approval_scope(NEW.id,v_origin);
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 SELECT NEW.id,v_origin,pp.id,'aberta','aprovada','aprovar_os',auth.uid(),jsonb_build_object(
 'organization_id',v_org,'before',jsonb_build_object('status',OLD.status,'volume',OLD.volume_total_ml,'data_os',to_jsonb(OLD)->'data_programada'),
 'after',jsonb_build_object('status',NEW.status,'volume',NEW.volume_total_ml,'data_os',to_jsonb(NEW)->'data_programada'),
 'programacao',jsonb_build_object('id',pp.id,'status',pp.status,'data',pp.data_programada,'volume',pp.volume_necessario),
 'actor',auth.uid(),'at',clock_timestamp(),'manufacturing_started',false,'commercial_completed',false)::text
 FROM public.programacao_producao pp WHERE pp.ordem_servico_id=NEW.id OR pp.ordem_servico_onfarm_id=NEW.id;
 END IF;
 RETURN NEW;
END $function$

