CREATE OR REPLACE FUNCTION public._comunicacao_trg_portal_solicitacao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ev text;
  v_transition text;
  v_idem text;
  v_status_ant text;
  v_status_novo text;
  v_first_assign boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_ev := 'solicitacao_criada';
    v_transition := 'insert';
    v_status_ant := NULL;
    v_status_novo := NEW.status::text;
    v_first_assign := (NEW.consultor_atribuido IS NOT NULL AND NEW.status = 'atribuida');
    -- Se INSERT já com status=atribuida, o evento canônico é solicitacao_criada
    -- (linha nova). A primeira atribuição via UPDATE é que precisa emitir
    -- 'solicitacao_atribuida' adicional; em INSERT, criada já é suficiente.
    v_first_assign := false;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      v_ev := CASE NEW.status
        WHEN 'atribuida' THEN 'solicitacao_atribuida'
        WHEN 'checkin_realizado' THEN 'solicitacao_checkin_realizado'
        WHEN 'em_visita' THEN 'solicitacao_em_visita'
        WHEN 'aguardando_os' THEN 'solicitacao_aguardando_os'
        WHEN 'concluida' THEN 'solicitacao_concluida'
        WHEN 'cancelada' THEN 'solicitacao_cancelada'
        ELSE NULL
      END;
      v_transition := 'status:' || COALESCE(NEW.status::text,'null');
      v_status_ant := OLD.status::text;
      v_status_novo := NEW.status::text;
    END IF;
    -- Primeira atribuição: consultor NULL→X. Deduplicação: se status já
    -- transicionou para 'atribuida' neste mesmo comando, o evento canônico
    -- já será emitido; não emitir de novo.
    IF OLD.consultor_atribuido IS NULL AND NEW.consultor_atribuido IS NOT NULL
       AND (v_ev IS DISTINCT FROM 'solicitacao_atribuida') THEN
      v_first_assign := true;
    END IF;
  END IF;

  IF v_ev IS NOT NULL THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|', v_ev, NEW.id::text, v_transition, COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      v_ev, 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_anterior', v_status_ant,
        'status_novo', v_status_novo,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', v_transition
      )),
      v_idem
    );
  END IF;

  IF v_first_assign THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|','solicitacao_atribuida', NEW.id::text,
                  'first_assign:'||NEW.consultor_atribuido::text,
                  COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      'solicitacao_atribuida', 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_novo', NEW.status::text,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', 'first_assign'
      )),
      v_idem
    );
  END IF;

  IF (TG_OP = 'INSERT' AND NEW.urgencia = 'critica')
     OR (TG_OP = 'UPDATE' AND NEW.urgencia = 'critica' AND OLD.urgencia IS DISTINCT FROM 'critica') THEN
    v_idem := 'solicitacao:' || encode(
      extensions.digest(
        concat_ws('|', 'solicitacao_urgencia_critica', NEW.id::text, 'urgencia:critica',
                  COALESCE(NEW.updated_at::text,'')),
        'sha256'
      ), 'hex'
    );
    PERFORM public._comunicacao_publish_system_event(
      'solicitacao_urgencia_critica', 'portal_solicitacoes', NEW.id,
      jsonb_strip_nulls(jsonb_build_object(
        'solicitacao_id', NEW.id,
        'numero', NEW.numero_solicitacao,
        'cliente_id', NEW.cliente_id,
        'fazenda_id', NEW.fazenda_id,
        'tipo_demanda', NEW.tipo_demanda,
        'urgencia', NEW.urgencia,
        'status_novo', NEW.status::text,
        'consultor_atribuido', NEW.consultor_atribuido,
        'origem_solicitacao', NEW.origem_solicitacao,
        'ocorrido_em', COALESCE(NEW.updated_at, now()),
        'transicao', 'urgencia:critica'
      )),
      v_idem
    );
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._saas_trg_require_feature()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_key text := TG_ARGV[0];
BEGIN
  IF v_uid IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.organizations o ON o.id = p.organization_id AND o.ativo IS TRUE
    WHERE p.user_id = v_uid AND p.ativo IS TRUE AND p.organization_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'saas_context_unavailable: usuário ativo e empresa são obrigatórios'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public._saas_user_has_feature(v_uid, v_key) THEN
    RAISE EXCEPTION 'saas_feature_not_entitled: funcionalidade não contratada ou assinatura indisponível'
      USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public._sync_planning_from_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_planning_id uuid;
  v_total int;
  v_done int;
  v_in_prod int;
BEGIN
  v_partner_order_id := COALESCE(NEW.partner_order_id, OLD.partner_order_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_planning_id FROM public.production_planning WHERE partner_order_id = v_partner_order_id;
  IF v_planning_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status IN ('finalizada','entregue','pronto_entrega')),
         COUNT(*) FILTER (WHERE status IN ('em_producao','em_cq','envase','programada'))
    INTO v_total, v_done, v_in_prod
  FROM public.ordens_servico WHERE partner_order_id = v_partner_order_id;

  IF v_total = 0 THEN RETURN NEW; END IF;

  IF v_done = v_total THEN
    UPDATE public.production_planning SET status='produzido', updated_at=now()
      WHERE id=v_planning_id AND status <> 'produzido';
  ELSIF v_in_prod > 0 THEN
    UPDATE public.production_planning SET status='em_producao', updated_at=now()
      WHERE id=v_planning_id AND status NOT IN ('em_producao','produzido','entregue');
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.auto_advance_solicitacao_on_os()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_solicitacao_id uuid;
BEGIN
  IF NEW.registro_consultor_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT solicitacao_id INTO v_solicitacao_id
    FROM public.registros_consultor WHERE id = NEW.registro_consultor_id;
  IF v_solicitacao_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes
      SET status = 'aguardando_os', updated_at = now()
      WHERE id = v_solicitacao_id
        AND status NOT IN ('concluida','cancelada');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_access_cliente(_cliente_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid := auth.uid();
    v_is_admin boolean;
    v_is_gestor boolean;
    v_is_adm_sys boolean;
    v_is_financeiro boolean;
    v_is_comercial boolean;
    v_is_producao boolean;
    v_is_aplicador boolean;
    v_is_onfarm boolean;
    v_is_consultor boolean;
    v_is_tecnico boolean;
    v_is_cliente boolean;
    v_is_b2b boolean;
    v_is_b2b_tec boolean;
    v_partner_id uuid;
BEGIN
    IF v_user_id IS NULL OR _cliente_id IS NULL THEN
        RETURN FALSE;
    END IF;

    v_is_admin := COALESCE(has_role(v_user_id, 'administrador'::app_role), false);
    v_is_gestor := COALESCE(has_role(v_user_id, 'gestor'::app_role), false);
    v_is_adm_sys := COALESCE(has_role(v_user_id, 'administrativo'::app_role), false);
    v_is_financeiro := COALESCE(has_role(v_user_id, 'financeiro'::app_role), false);
    v_is_comercial := COALESCE(has_role(v_user_id, 'gestor_comercial'::app_role), false);
    v_is_producao := COALESCE(has_role(v_user_id, 'producao'::app_role), false);
    v_is_aplicador := COALESCE(has_role(v_user_id, 'aplicador'::app_role), false);
    v_is_onfarm := COALESCE(has_role(v_user_id, 'operador_onfarm'::app_role), false);
    v_is_consultor := COALESCE(has_role(v_user_id, 'consultor_tecnico'::app_role), false);
    v_is_tecnico := COALESCE(has_role(v_user_id, 'tecnico_agronomo'::app_role), false);
    v_is_cliente := COALESCE(has_role(v_user_id, 'cliente_produtor'::app_role), false);
    v_is_b2b := COALESCE(has_role(v_user_id, 'parceiro_b2b'::app_role), false);
    v_is_b2b_tec := COALESCE(has_role(v_user_id, 'parceiro_b2b_tecnico'::app_role), false);

    IF v_is_admin OR v_is_gestor OR v_is_adm_sys OR v_is_financeiro
       OR v_is_comercial OR v_is_producao OR v_is_aplicador OR v_is_onfarm THEN
        RETURN TRUE;
    END IF;

    IF v_is_cliente THEN
        RETURN COALESCE(_cliente_id = ANY(get_cliente_ids_for_user(v_user_id)), false);
    END IF;

    -- HARDENING: carteira ativa e vigente é obrigatória para papéis técnicos.
    IF v_is_consultor OR v_is_tecnico THEN
        RETURN COALESCE(
          public.has_active_user_cliente_access(
            v_user_id, _cliente_id, ARRAY['read','execute','manage']
          ), false);
    END IF;

    IF v_is_b2b_tec THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.technician_user_id = v_user_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          )), false);
    END IF;

    IF v_is_b2b THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          ) OR EXISTS (
            SELECT 1 FROM public.partner_clients pc
            WHERE pc.cliente_id = _cliente_id
              AND pc.partner_id = v_partner_id
              AND pc.active = true
          )), false);
    END IF;

    RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_user_access_estoque_embalagem(p_embalagem_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_cli uuid; v_status text; v_entrega uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  SELECT cliente_id, status, entrega_id INTO v_cli, v_status, v_entrega
    FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role) THEN
    RETURN true;
  END IF;
  IF public.has_role(v_uid,'financeiro'::app_role) THEN
    RETURN v_entrega IS NOT NULL;
  END IF;
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role) THEN
    RETURN v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    RETURN v_status='entregue' AND v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.can_user_access_produto_etiqueta(p_etiqueta_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_cliente_id uuid;
  v_gerada_por uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  -- Perfis internos com acesso total
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role)
     OR public.has_role(v_uid,'financeiro'::app_role)
  THEN
    RETURN true;
  END IF;

  SELECT cliente_id, gerada_por
    INTO v_cliente_id, v_gerada_por
    FROM public.produto_etiquetas
   WHERE id = p_etiqueta_id;

  IF NOT FOUND THEN RETURN false; END IF;

  -- Cliente produtor: apenas etiquetas dos seus clientes
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    IF v_cliente_id IS NULL THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    );
  END IF;

  -- Consultor/técnico: regra conservadora — apenas se gerada por ele
  -- ou se estiver vinculado ao cliente em user_clientes
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role)
  THEN
    IF v_gerada_por = v_uid THEN RETURN true; END IF;
    IF v_cliente_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    ) THEN
      RETURN true;
    END IF;
    RETURN false;
  END IF;

  RETURN false;
END;
$function$

