CREATE OR REPLACE FUNCTION public.fn_entrega_comprovante_preservar_encerrado_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 v_operacionais text[]:=ARRAY['updated_at','metadata','qr_code_path','qr_code_generated_at','validation_public_enabled','validation_expires_at','validation_url'];
 v_campo text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status='confirmado' OR OLD.metadata ? 'comprovante_snapshot_v1' THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Comprovante encerrado não pode ser excluído.';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.status='confirmado' AND
   (to_jsonb(NEW)-v_operacionais) IS DISTINCT FROM (to_jsonb(OLD)-v_operacionais) THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Dados do comprovante confirmado não podem ser alterados.';
 END IF;
 IF OLD.metadata ? 'comprovante_snapshot_v1' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Vínculo do comprovante congelado não pode ser alterado.';
  END IF;
  FOREACH v_campo IN ARRAY ARRAY['comprovante_snapshot_v1','comprovante_snapshot_hash','comprovante_numero'] LOOP
   IF NEW.metadata->v_campo IS DISTINCT FROM OLD.metadata->v_campo THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Conteúdo do comprovante congelado não pode ser alterado.';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END;
$function$

