CREATE OR REPLACE FUNCTION public.trg_clientes_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    old_val JSONB := NULL;
    new_val JSONB := NULL;
    v_diff JSONB := '{}'::jsonb;
BEGIN
    IF (TG_OP = 'UPDATE') THEN
        old_val := to_jsonb(OLD);
        new_val := to_jsonb(NEW);
        SELECT jsonb_object_agg(key, value) INTO v_diff FROM jsonb_each(new_val) WHERE new_val->key IS DISTINCT FROM old_val->key;
    ELSIF (TG_OP = 'INSERT') THEN
        new_val := to_jsonb(NEW);
    ELSIF (TG_OP = 'DELETE') THEN
        old_val := to_jsonb(OLD);
    END IF;

    INSERT INTO public.clientes_audit_log (cliente_id, action, changed_by, old_data, new_data, diff)
    VALUES (COALESCE(NEW.id, OLD.id), TG_OP, auth.uid(), old_val, new_val, v_diff);

    RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_entrega_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_total int; v_delivered int;
BEGIN
  SELECT os.partner_order_id INTO v_partner_order_id
    FROM public.ordens_servico os WHERE os.id = COALESCE(NEW.ordem_servico_id, OLD.ordem_servico_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE e.status = 'entregue')
    INTO v_total, v_delivered
    FROM public.entregas e
    JOIN public.ordens_servico os ON os.id = e.ordem_servico_id
   WHERE os.partner_order_id = v_partner_order_id;

  IF v_total > 0 AND v_delivered = v_total THEN
    UPDATE public.partner_orders SET status = 'entregue', updated_at = now()
      WHERE id = v_partner_order_id AND status <> 'entregue';
    UPDATE public.production_planning SET status = 'entregue', updated_at = now()
      WHERE partner_order_id = v_partner_order_id;
    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (v_partner_order_id, 'entrega_realizada', jsonb_build_object('total', v_total));
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_mestre_guard_preco_canonico()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_litro numeric;
  v_tiers integer;
BEGIN
  IF COALESCE(current_setting('arbio.catalogo_sync', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_TABLE_NAME = 'produtos' THEN
    SELECT litro, tiers INTO v_litro, v_tiers FROM public.fn_catalogo_litro_canonico(NEW.id, NULL);
    IF COALESCE(v_tiers,0) = 0 THEN RETURN NEW; END IF;
    IF v_tiers = 1 AND COALESCE(v_litro,0) > 0 THEN
      NEW.valor_litro_brl := v_litro;
      NEW.valor_dose_brl  := round(v_litro / 10.0, 2);
      NEW.valor_ha_brl    := CASE WHEN COALESCE(NEW.dose_ml_ha,0) > 0
                                  THEN round(v_litro * (NEW.dose_ml_ha / 1000.0), 2) END;
    ELSE
      NEW.valor_litro_brl := NULL; NEW.valor_dose_brl := NULL; NEW.valor_ha_brl := NULL;
    END IF;
  ELSE
    SELECT litro, tiers INTO v_litro, v_tiers FROM public.fn_catalogo_litro_canonico(NULL, NEW.id);
    IF COALESCE(v_tiers,0) = 0 THEN RETURN NEW; END IF;
    IF v_tiers = 1 AND COALESCE(v_litro,0) > 0 THEN
      NEW.valor_litro_brl := v_litro;
      NEW.valor_dose_brl  := round(v_litro / 10.0, 2);
    ELSE
      NEW.valor_litro_brl := NULL; NEW.valor_dose_brl := NULL;
    END IF;
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_os_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_partner_order_id uuid; v_total int; v_done int; v_in_prod int;
 v_new_status public.partner_order_status; v_old_status public.partner_order_status; v_nonlab int;
BEGIN
 v_partner_order_id:=coalesce(NEW.partner_order_id,OLD.partner_order_id);
 IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
 SELECT count(*),count(*) FILTER(WHERE status IN ('pronto_entrega','entregue','finalizada')),
 count(*) FILTER(WHERE status IN ('em_producao','em_cq','envase','programada')) INTO v_total,v_done,v_in_prod
 FROM public.ordens_servico WHERE partner_order_id=v_partner_order_id;
 SELECT count(*) INTO v_nonlab FROM public.partner_order_items i WHERE i.order_id=v_partner_order_id
 AND NOT platform_private.lab_item_is_manufacturable(i.product_id,i.microrganismo_id);
 SELECT status INTO v_old_status FROM public.partner_orders WHERE id=v_partner_order_id;
 IF v_total>0 AND v_done=v_total AND v_nonlab=0 THEN v_new_status:='produzido';
 ELSIF v_in_prod>0 THEN v_new_status:='em_producao';
 ELSE v_new_status:=v_old_status; END IF;
 -- Pedido misto nunca é declarado integralmente produzido apenas por conclusão das OS biológicas.
 IF v_new_status IS DISTINCT FROM v_old_status THEN
  UPDATE public.partner_orders SET status=v_new_status,updated_at=now() WHERE id=v_partner_order_id;
  UPDATE public.production_planning SET status=v_new_status::text::public.production_planning_status,updated_at=now() WHERE partner_order_id=v_partner_order_id;
  INSERT INTO public.production_timeline_events(partner_order_id,event_type,meta) VALUES(v_partner_order_id,
  CASE WHEN v_new_status='produzido' THEN 'producao_finalizada' ELSE 'producao_iniciada' END,jsonb_build_object('from',v_old_status,'to',v_new_status));
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_partner_order_timeline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, actor_id, meta)
    VALUES (NEW.id, 'pedido_criado', NEW.created_at, NEW.created_by, '{}'::jsonb);
  ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'aprovado' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'pedido_aprovado', now(), '{}'::jsonb);
    ELSIF NEW.status = 'em_producao' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'producao_iniciada', now(), '{}'::jsonb);
    ELSIF NEW.status IN ('produzido','aguardando_entrega') THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'producao_finalizada', now(), '{}'::jsonb);
    ELSIF NEW.status = 'entregue' THEN
      INSERT INTO public.production_timeline_events(partner_order_id, event_type, event_at, meta)
      VALUES (NEW.id, 'entrega_realizada', now(), '{}'::jsonb);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_estoque_entrada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Reservas parciais (têm quantidade_reservada preenchida) seguem normalmente
  IF NEW.quantidade_reservada IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Exigir envase para o lote
  IF NOT EXISTS (SELECT 1 FROM public.envase WHERE lote_id = NEW.lote_id) THEN
    RAISE EXCEPTION 'Não é possível criar entrada no estoque: o lote ainda não possui registro de envase.'
      USING ERRCODE = 'check_violation';
  END IF;

  -- Bloquear duplicidade por envase_id (não mais por lote)
  IF NEW.envase_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE envase_id = NEW.envase_id
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe entrada de estoque para este envase.'
      USING ERRCODE = 'unique_violation';
  END IF;

  -- Compat: se a entrada vier sem envase_id, manter a regra antiga de 1 por lote
  IF NEW.envase_id IS NULL AND EXISTS (
    SELECT 1 FROM public.estoque_produto
    WHERE lote_id = NEW.lote_id
      AND envase_id IS NULL
      AND quantidade_reservada IS NULL
      AND id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
  ) THEN
    RAISE EXCEPTION 'Já existe uma entrada de estoque agregada para este lote.'
      USING ERRCODE = 'unique_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_estoque_reserva()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status::text = 'reservado' AND (OLD.status IS DISTINCT FROM NEW.status OR OLD.status::text <> 'reservado') THEN
    IF NEW.reservado_para_os_id IS NULL THEN
      RAISE EXCEPTION 'Reserva requer uma OS vinculada.' USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.reservado_para_os_tipo = 'b2b' THEN
      IF NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva B2B requer um parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.reservado_para_cliente_id IS NULL AND NEW.reservado_para_partner_id IS NULL THEN
        RAISE EXCEPTION 'Reserva requer um cliente ou parceiro vinculado.' USING ERRCODE = 'check_violation';
      END IF;
    END IF;

    IF NEW.quantidade_reservada IS NULL OR NEW.quantidade_reservada <= 0 THEN
      RAISE EXCEPTION 'Informe uma quantidade reservada maior que zero.' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.quantidade IS NOT NULL AND NEW.quantidade_reservada > NEW.quantidade THEN
      RAISE EXCEPTION 'Quantidade reservada (%) excede o estoque disponível (%).', NEW.quantidade_reservada, NEW.quantidade
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.reservado_em IS NULL THEN NEW.reservado_em := now(); END IF;
    IF NEW.reservado_por IS NULL THEN NEW.reservado_por := auth.uid(); END IF;
  END IF;

  IF NEW.status::text = 'disponivel' AND OLD.status::text = 'reservado' THEN
    NEW.reservado_para_os_id := NULL;
    NEW.reservado_para_os_tipo := NULL;
    NEW.reservado_para_cliente_id := NULL;
    NEW.reservado_para_partner_id := NULL;
    NEW.reservado_para_partner_order_id := NULL;
    NEW.quantidade_reservada := NULL;
    NEW.reservado_por := NULL;
    NEW.reservado_em := NULL;
    NEW.observacao_reserva := NULL;
  END IF;

  IF NEW.status::text = 'expedido' AND OLD.status::text <> 'expedido' THEN
    IF NEW.expedido_em IS NULL THEN NEW.expedido_em := now(); END IF;
    IF NEW.expedido_por IS NULL THEN NEW.expedido_por := auth.uid(); END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_responsavel_producao()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_ok boolean;
BEGIN
  IF NEW.responsavel_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT user_id INTO v_user_id
  FROM public.profiles
  WHERE id = NEW.responsavel_id;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Responsável inválido: perfil não encontrado'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = v_user_id
      AND role::text IN ('administrador','gestor','operador_onfarm','producao')
  ) INTO v_ok;

  IF NOT v_ok THEN
    RAISE EXCEPTION 'Responsável inválido: perfil sem permissão para produção do laboratório'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_retorno_tecnico_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    has_overlap BOOLEAN;
    visit_duration INTEGER;
BEGIN
    -- Se tem data e consultor, validar sobreposição (independente do tipo de demanda)
    IF NEW.data_prevista_atendimento IS NOT NULL AND NEW.consultor_atribuido IS NOT NULL THEN

        -- Duração padrão de 120 min se não informado
        visit_duration := COALESCE(NEW.duracao_estimada, 120);

        -- Verificar sobreposições
        -- Consideramos que uma visita ocupa o intervalo [data, data + duracao]
        SELECT EXISTS (
            SELECT 1 FROM portal_solicitacoes
            WHERE consultor_atribuido = NEW.consultor_atribuido
            AND id <> NEW.id -- desconsiderar a própria
            AND data_prevista_atendimento IS NOT NULL
            AND status NOT IN ('concluida', 'cancelada')
            AND (
                -- Caso A: Nova visita começa DURANTE uma existente
                (NEW.data_prevista_atendimento >= data_prevista_atendimento AND NEW.data_prevista_atendimento < (data_prevista_atendimento + (COALESCE(duracao_estimada, 120) || ' minutes')::interval))
                OR
                -- Caso B: Visita existente começa DURANTE a nova
                (data_prevista_atendimento >= NEW.data_prevista_atendimento AND data_prevista_atendimento < (NEW.data_prevista_atendimento + (visit_duration || ' minutes')::interval))
            )
        ) INTO has_overlap;

        IF has_overlap THEN
            RAISE EXCEPTION 'CONFLITO_AGENDA: Já existe uma visita agendada para este consultor neste horário ou intervalo.';
        END IF;
    END IF;

    -- Validações específicas para o tipo 'retorno_tecnico'
    IF NEW.tipo_demanda = 'retorno_tecnico' THEN
        -- Validar data obrigatória e no futuro (tolerância de 1h)
        IF NEW.data_prevista_atendimento IS NULL THEN
            RAISE EXCEPTION 'Data prevista é obrigatória para retornos técnicos.';
        END IF;

        IF NEW.data_prevista_atendimento < now() - interval '1 hour' THEN
            RAISE EXCEPTION 'A data do retorno não pode ser no passado.';
        END IF;

        -- Validar descrição/motivo
        IF NEW.descricao IS NULL OR length(trim(NEW.descricao)) < 5 THEN
            RAISE EXCEPTION 'O motivo do retorno deve ser detalhado na descrição.';
        END IF;

        -- Validar consultor
        IF NEW.consultor_atribuido IS NULL THEN
            RAISE EXCEPTION 'Um consultor deve estar atribuído ao retorno.';
        END IF;

        -- Validar duração
        IF NEW.duracao_estimada IS NULL OR NEW.duracao_estimada <= 0 THEN
             RAISE EXCEPTION 'Duração estimada é obrigatória para retornos técnicos.';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.visitas_campo_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Initial contract: a new row always starts at version 1.
    IF NEW.versao IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'versao_inicial_invalida' USING ERRCODE = 'PT409';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.registro_consultor_id IS DISTINCT FROM OLD.registro_consultor_id THEN
    RAISE EXCEPTION 'campo_imutavel_registro_consultor_id' USING ERRCODE = '42501';
  END IF;
  IF NEW.cliente_id IS DISTINCT FROM OLD.cliente_id THEN
    RAISE EXCEPTION 'campo_imutavel_cliente_id' USING ERRCODE = '42501';
  END IF;
  IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'campo_imutavel_created_by' USING ERRCODE = '42501';
  END IF;
  IF OLD.client_uuid IS NOT NULL AND NEW.client_uuid IS DISTINCT FROM OLD.client_uuid THEN
    RAISE EXCEPTION 'campo_imutavel_client_uuid' USING ERRCODE = '42501';
  END IF;
  -- Strict +1: no NULL, no jump, no repeat, no regression (applies to every writer).
  IF OLD.versao IS NULL OR NEW.versao IS NULL OR NEW.versao <> OLD.versao + 1 THEN
    RAISE EXCEPTION 'versao_deve_incrementar' USING ERRCODE = 'PT409';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_private.b2b_internal_assert_origin(s jsonb, partner uuid, client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; uid uuid:=auth.uid();
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL OR NOT public.fn_cc_can_prepare(uid) OR NOT public._saas_user_has_feature(uid,'pedidos_b2b') THEN RAISE EXCEPTION 'B2B_INTERNAL_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT platform_private.b2b_internal_origin_valid(s) OR s->>'organization_id' IS DISTINCT FROM org::text OR s->>'partner_id' IS DISTINCT FROM partner::text THEN RAISE EXCEPTION 'B2B_INTERNAL_ORIGIN_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.partner_accounts p WHERE p.id=partner AND p.commercial_owner_organization_id=org AND p.ativo IS TRUE AND p.deleted_at IS NULL
 AND (p.client_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=p.client_id AND c.organization_id=org))) THEN RAISE EXCEPTION 'B2B_INTERNAL_PARTNER_DENIED' USING ERRCODE='42501'; END IF;
 IF client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=client AND c.organization_id=org) THEN RAISE EXCEPTION 'B2B_INTERNAL_CLIENT_DENIED' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_external_origin_assert(s jsonb, partner uuid, client uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE uid uuid:=auth.uid(); org uuid; p public.partner_accounts;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.partner_accounts WHERE id=partner FOR SHARE;
 org:=p.commercial_owner_organization_id;
 IF NOT FOUND OR p.ativo IS NOT TRUE OR p.deleted_at IS NOT NULL OR org IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=org AND o.ativo AND o.status='ativa')
 OR EXISTS(SELECT 1 FROM public.organizations o WHERE o.partner_account_id=partner)
 OR NOT platform_private.c2_external_origin_contract_valid(s)
 OR s->>'organization_id' IS DISTINCT FROM org::text OR s->>'partner_id' IS DISTINCT FROM partner::text
 THEN RAISE EXCEPTION 'C2_EXTERNAL_ORIGIN_DENIED' USING ERRCODE='42501'; END IF;
 IF client IS DISTINCT FROM p.client_id OR (client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=client AND c.organization_id=org))
 THEN RAISE EXCEPTION 'C2_EXTERNAL_CLIENT_DENIED' USING ERRCODE='42501'; END IF;
 -- Initial writes are authorized only inside the existing canonical create transaction.
 -- Subsequent administration uses P1's active internal owner authority, never buyer roles.
 IF platform_private.has_ticket('c2_external_order_create',partner) THEN
  IF s->>'actor_user_id' IS DISTINCT FROM uid::text OR NOT platform_private.c2_owner_order_create_allowed(uid,partner)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_CREATE_DENIED' USING ERRCODE='42501'; END IF;
  ELSE
  IF public.h15_actor_organization() IS DISTINCT FROM org OR NOT platform_private.c2p1_settings_allowed(partner,true)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_OWNER_DENIED' USING ERRCODE='42501'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION platform_private.c2_owner_order_create_allowed(_uid uuid, _partner uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c jsonb;
BEGIN
  -- c2_ord_writer_v1: nunca confia em parâmetro de uid que não seja o JWT atual.
  IF _uid IS NULL OR _partner IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RETURN false; END IF;
  -- Gestor B2B vigente (user_roles canônico; revogação remove a linha). Técnico isolado nunca compra.
  IF NOT public.has_role(_uid,'parceiro_b2b'::public.app_role) THEN RETURN false; END IF;
  c := platform_private.b2b_commercial_context();
  IF c IS NULL OR c->>'contract' <> 'C2_MULTIPROFILE_V1' OR c->>'mode' <> 'commercial_owner'
     OR (c->>'partner_id')::uuid IS DISTINCT FROM _partner OR COALESCE((c->>'manager')::boolean,false) IS NOT TRUE THEN
    RETURN false;
  END IF;
  -- Cliente comercial = sem organização própria; tenant dono ativo e coerente com perfil/vínculo.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN false; END IF;
  IF NOT COALESCE(platform_private.b2b_phase1_partner_visible(_partner,true),false) THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_users pu
      JOIN public.partner_accounts pa ON pa.id = pu.partner_id
      JOIN public.profiles p ON p.user_id = pu.user_id
      JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pu.user_id = _uid AND pu.partner_id = _partner
       AND pu.revoked_at IS NULL AND (pu.valid_from IS NULL OR pu.valid_from <= now())
       AND pa.ativo AND pa.deleted_at IS NULL AND o.ativo AND o.status = 'ativa'
       AND (o.partner_account_id IS NULL OR o.partner_account_id = _partner)
       AND p.ativo AND p.organization_id = pu.tenant_id AND pu.tenant_id = o.id
       AND (c->>'tenant_id')::uuid = o.id
       AND public.is_valid_b2b_partner_user(_uid, pa.id)) THEN
    RETURN false;
  END IF;
  RETURN EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'pedidos_b2b')
     AND EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'catalogo_precos');
END $function$

CREATE OR REPLACE FUNCTION platform_private.catalog_tenant_actor(p_mode text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_claims jsonb := NULLIF(current_setting('request.jwt.claims', true), '')::jsonb;
  v_org uuid;
BEGIN
  IF v_uid IS NULL OR v_claims IS NULL OR v_claims->>'role' IS DISTINCT FROM 'authenticated'
     OR (v_claims->>'sub') IS DISTINCT FROM v_uid::text
     OR NULLIF(v_claims->>'exp','') IS NULL OR (v_claims->>'exp') !~ '^[0-9]{1,12}$'
     OR to_timestamp((v_claims->>'exp')::bigint) <= now()
     OR (NULLIF(v_claims->>'iat','') IS NOT NULL AND ((v_claims->>'iat') !~ '^[0-9]{1,12}$'
         OR to_timestamp((v_claims->>'iat')::bigint) > now() + interval '60 seconds')) THEN
    RAISE EXCEPTION 'catalog_visibility_auth_required' USING ERRCODE='42501';
  END IF;
  IF public.is_platform_superadmin(v_uid) THEN
    RAISE EXCEPTION 'catalog_visibility_platform_actor_denied' USING ERRCODE='42501';
  END IF;
  v_org := platform_private.h15_actor_organization();
  IF v_org IS NULL OR NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id=v_org AND o.ativo IS TRUE AND o.status='ativa') THEN
    RAISE EXCEPTION 'catalog_visibility_tenant_unavailable' USING ERRCODE='42501';
  END IF;
  IF p_mode IN ('mutate','read_catalog','read_management') AND NOT public._saas_user_has_feature(v_uid, 'catalogo_precos') THEN
    RAISE EXCEPTION 'catalog_visibility_feature_unavailable' USING ERRCODE='42501';
  END IF;
  IF p_mode='mutate' THEN
    IF NOT (platform_private.has_role(v_uid,'administrador'::public.app_role) OR platform_private.has_role(v_uid,'gestor'::public.app_role)) THEN
      RAISE EXCEPTION 'catalog_visibility_role_denied' USING ERRCODE='42501'; END IF;
  ELSIF p_mode='read_catalog' THEN
    IF NOT public.can_view_catalog_internal(v_uid) THEN
      RAISE EXCEPTION 'catalog_visibility_role_denied' USING ERRCODE='42501'; END IF;
  ELSIF p_mode NOT IN ('read_management','read_selection_cultura','read_prefs') OR p_mode IS NULL THEN
    RAISE EXCEPTION 'catalog_visibility_mode_invalid' USING ERRCODE='22023';
  END IF;
  RETURN v_org;
END; $function$

CREATE OR REPLACE FUNCTION platform_private.delivery_actor_20261030(p_action text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_org uuid; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'DELIVERY_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor','consultor_tecnico','aplicador','operador_onfarm','superadmin'))
 OR EXISTS(SELECT 1 FROM public.partner_users WHERE user_id=auth.uid() AND revoked_at IS NULL AND (valid_from IS NULL OR valid_from<=pg_catalog.now()))
 OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role IN ('administrador','gestor') OR (p_action='group' AND role='producao') OR (p_action='cancel' AND role='administrativo')))
 THEN RAISE EXCEPTION 'DELIVERY_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT public.saas_has_feature('estoque_embalagens') THEN RAISE EXCEPTION 'DELIVERY_FEATURE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN v_org;
END $function$

CREATE OR REPLACE FUNCTION platform_private.notification_source_org(st text, sid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v uuid; BEGIN
 IF sid IS NULL THEN RETURN NULL; END IF;
 CASE st
 WHEN 'registros_consultor','registro_consultor','monitoramento_vencido' THEN SELECT c.organization_id INTO v FROM public.registros_consultor r JOIN public.clientes c ON c.id=r.cliente_id WHERE r.id=sid;
 WHEN 'ordem_servico','ordens_servico' THEN SELECT o.organization_id INTO v FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE o.id=sid;
 WHEN 'portal_solicitacoes' THEN SELECT c.organization_id INTO v FROM public.portal_solicitacoes s JOIN public.clientes c ON c.id=s.cliente_id WHERE s.id=sid;
 WHEN 'programacao_producao' THEN SELECT p.organization_id INTO v FROM public.programacao_producao p WHERE p.id=sid AND ((p.ordem_servico_id IS NOT NULL AND p.ordem_servico_onfarm_id IS NULL AND EXISTS(SELECT 1 FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE o.id=p.ordem_servico_id AND o.organization_id=p.organization_id)) OR (p.ordem_servico_onfarm_id IS NOT NULL AND p.ordem_servico_id IS NULL AND EXISTS(SELECT 1 FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=p.ordem_servico_onfarm_id AND c.organization_id=p.organization_id)));
 WHEN 'estoque_produto' THEN RETURN NULL;
 WHEN 'aplicacao','aplicacoes' THEN SELECT a.organization_id INTO v FROM public.aplicacoes a JOIN public.ordens_servico o ON o.id=a.ordem_servico_id AND o.organization_id=a.organization_id JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE a.id=sid AND a.ordem_servico_onfarm_id IS NULL;
 WHEN 'partner_orders' THEN SELECT c.organization_id INTO v FROM public.partner_orders o JOIN public.partner_accounts p ON p.id=o.partner_id AND p.ativo IS TRUE AND p.deleted_at IS NULL JOIN public.clientes c ON c.id=p.client_id WHERE o.id=sid;
 WHEN 'partner_simulations' THEN SELECT c.organization_id INTO v FROM public.partner_simulations s JOIN public.partner_accounts p ON p.id=s.partner_id AND p.ativo IS TRUE AND p.deleted_at IS NULL JOIN public.clientes c ON c.id=p.client_id WHERE s.id=sid;
 ELSE RETURN NULL; END CASE;
 IF NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=v AND o.ativo IS TRUE) THEN RETURN NULL; END IF;
 RETURN v; END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_envase_scope_v1(p_lote uuid, p_prog uuid, p_os uuid, p_origem text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE org uuid; p public.programacao_producao%ROWTYPE; o public.ordens_servico%ROWTYPE; l public.lotes%ROWTYPE;
BEGIN
 org:=platform_private.stock_motor_actor('reserva');
 IF public.technical_actor_ready(auth.uid()) IS NOT TRUE OR public._saas_user_has_feature(auth.uid(),'envase') IS NOT TRUE
 OR public._saas_user_has_feature(auth.uid(),'ordens_producao') IS NOT TRUE THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF public.fn_cockpit_norm_origem(p_origem) IS DISTINCT FROM 'manual' THEN RAISE EXCEPTION 'ENVASE_ORIGIN_COMPOSITION_PENDING' USING ERRCODE='42501'; END IF;
 IF (public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'producao')) IS NOT TRUE THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.programacao_producao WHERE id=p_prog AND organization_id=org;
 IF NOT FOUND OR p.ordem_servico_id IS DISTINCT FROM p_os OR p.ordem_servico_onfarm_id IS NOT NULL THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO o FROM public.ordens_servico WHERE id=p_os AND organization_id=org;
 IF NOT FOUND OR o.partner_order_id IS NOT NULL OR o.partner_order_item_id IS NOT NULL OR o.origem IS DISTINCT FROM 'agronomica'
 OR NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=o.cliente_id AND organization_id=org) THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO l FROM public.lotes WHERE id=p_lote AND organization_id=org;
 IF NOT FOUND OR l.programacao_id IS DISTINCT FROM p_prog OR l.produto_id IS DISTINCT FROM p.produto_id
 OR l.microrganismo_id IS DISTINCT FROM p.microrganismo_id THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN org;
END $function$

CREATE OR REPLACE FUNCTION platform_private.stock_motor_actor(p_acao text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ DECLARE v_org uuid; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'ESTQ_NAO_AUTENTICADO' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
