CREATE OR REPLACE FUNCTION platform_private.tenant_smtp_lane_source_reason(p_source uuid, p_cliente uuid, p_org uuid, p_recipient uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s record; c record;
BEGIN
 SELECT id,cliente_id,consultor_atribuido,status::text AS status INTO s FROM public.portal_solicitacoes WHERE id=p_source;
 IF NOT FOUND THEN RETURN 'source_missing'; END IF;
 IF s.cliente_id IS DISTINCT FROM p_cliente THEN RETURN 'source_client_changed'; END IF;
 IF s.consultor_atribuido IS NULL THEN RETURN 'source_unassigned'; END IF;
 IF s.consultor_atribuido IS DISTINCT FROM p_recipient THEN RETURN 'source_reassigned'; END IF;
 IF s.status IS NULL OR s.status NOT IN ('pendente','atribuida') THEN RETURN 'source_state_ineligible'; END IF;
 SELECT organization_id,status_cliente::text AS st INTO c FROM public.clientes WHERE id=p_cliente;
 IF NOT FOUND OR c.organization_id IS DISTINCT FROM p_org THEN RETURN 'client_tenant_changed'; END IF;
 IF c.st IS DISTINCT FROM 'ativo' THEN RETURN 'client_ineligible'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_recipient AND uc.cliente_id=p_cliente
  AND uc.is_active IS TRUE AND uc.revoked_at IS NULL AND (uc.valid_from IS NULL OR uc.valid_from<=now())
  AND (uc.valid_until IS NULL OR uc.valid_until>=now()) AND uc.access_level::text IN ('read','execute','manage')) THEN RETURN 'recipient_portfolio_revoked'; END IF;
 IF platform_private.tenant_smtp_lane_recipient(p_org,p_recipient) IS NULL THEN RETURN 'recipient_unproven'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public._assert_visita_editavel(p_registro_id uuid)
 RETURNS registros_consultor
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_ok boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_reg FROM public.registros_consultor WHERE id = p_registro_id;
  IF v_reg.id IS NULL THEN RAISE EXCEPTION 'registro_nao_encontrado' USING ERRCODE = 'P0002'; END IF;

  v_ok := COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false)
       OR COALESCE(v_reg.created_by = v_uid, false)
       OR COALESCE(v_reg.consultor_responsavel = v_uid, false)
       OR COALESCE(public.is_active_visit_participant(v_uid, p_registro_id), false);

  IF v_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_technical_visit_editable_status(v_reg.status::text) THEN
    RAISE EXCEPTION 'visita_nao_editavel' USING ERRCODE = '42501';
  END IF;

  RETURN v_reg;
END;
$function$

